script:
carrier_event = {
	id = distar.31
	title = "distar.31.name"
	desc = "distar.31.desc"
	picture = GFX_evt_news_room
	show_sound = event_radio_chatter
	location = from

	is_triggered_only = yes

	trigger = {
		exists = owner
		any_owned_pop_group = {
			NOR = {	has_trait = trait_mechanical has_trait = trait_machine_unit	}
		}
	}

	immediate = {
		IF = {
			limit = {
				count_owned_pop_amount = {
					limit = { NOT = { has_trait = trait_mechanical } }
					count <= 500
				}
			}
			while = {
				count = 2
				weighted_random_owned_pop_group = {
					limit = {
						NOR = {
							has_trait = trait_mechanical
							has_trait = trait_machine_unit
							has_modifier = erratic_behavior
						}
					}
					add_modifier = { modifier = erratic_behavior days = -1 }
				}
			}
		}
		else_if = {
			limit = {
				count_owned_pop_amount = {
					limit = { NOT = { has_trait = trait_mechanical } }
					count >= 600
				}
				count_owned_pop_amount = {
					limit = { NOT = { has_trait = trait_mechanical } }
					count <= 1200
				}
			}
			while = {
				count = 3
				weighted_random_owned_pop_group = {
					limit = {
						NOR = {
							has_trait = trait_mechanical
							has_trait = trait_machine_unit
							has_modifier = erratic_behavior
						}
					}
					add_modifier = { modifier = erratic_behavior days = -1 }
				}
			}
		}
		else = {
			while = {
				count = 5
				weighted_random_owned_pop_group = {
					limit = {
						NOR = {
							has_trait = trait_mechanical
							has_trait = trait_machine_unit
							has_modifier = erratic_behavior
						}
					}
					add_modifier = { modifier = erratic_behavior days = -1 }
				}
			}
		}
	}

	option = {
		name = "distar.31.a"
		enable_special_project = {
			name = "RETROVIRUS_PROJECT"
			location = root
			owner = root.owner
		}
		hidden_effect = {
			carrier_event = { id = distar.32 days = 60 }
			carrier_event = { id = distar.33 days = 120 }
		}
	}
}

