						consume_selection = yes
					}
					save_global_event_target_as = warform_leader
					set_age = 1578
				}
			}
			create_fleet = {
				name = "NAME_S8751"
				effect = {
					set_owner = prev
					create_ship = {
						name = "NAME_S8751"
						design = "NAME_S8751"
						prefix = no
						upgradable = yes
					}
