					exists = owner
					owner = {
						is_same_value =	event_target:ratling_country
					}
					root = {
						intel_level = {
							level > none
							system = prev
						}
					}
				}
				save_event_target_as = sensor_ratling_system
			}
		}
		ELSE = { #Nothing
		}
	}

	option = {
		name = INTERESTING
	}

	option = {
